var C = ARISTO.colors;
var steepIn = document.getElementById('steep');
var tposIn = document.getElementById('tpos');
var tangentBtn = document.getElementById('tangent');
var showTangent = false;

// trip geometry:
// seg1: t in [0,4], d from 0 to 20 (5 m/s)
// seg2: t in [4,7], slope = steep (m/s), d from 20 to 20+3*steep
// seg3: t in [7,9], straight at 10 m/s, as in the lesson's worked example
// seg4: t in [9,12], curve: speed goes from 10 to 20 m/s linearly, so
//   v(t) = 10 + (10/3)*(t-9)
//   d(t) = d3 + 10*(t-9) + (5/3)*(t-9)^2, with d3 = d1seg2 + 20

function d0seg2() { return 20; }
function d1seg2(steep) { return 20 + 3 * steep; }

function distAt(t, steep) {
  if (t <= 4) {
    return 5 * t;
  } else if (t <= 7) {
    return 20 + steep * (t - 4);
  } else if (t <= 9) {
    return d1seg2(steep) + 10 * (t - 7);
  } else {
    var dt = t - 9;
    return d1seg2(steep) + 20 + 10 * dt + (5 / 3) * dt * dt;
  }
}

function speedAt(t, steep) {
  if (t <= 4) {
    return 5;
  } else if (t <= 7) {
    return steep;
  } else if (t <= 9) {
    return 10;
  } else {
    return 10 + (10 / 3) * (t - 9);
  }
}

function fmt(n) {
  return (Math.round(n * 10) / 10).toString();
}

var plot = ARISTO.canvas(document.getElementById('plot'), function (ctx, w, h) {
  var steep = +steepIn.value;
  var tpos = +tposIn.value;
  var padL = 36, padB = 26, padT = 10, padR = 10;
  var gw = w - padL - padR, gh = h - padT - padB;
  var tmax = 12, dmax = 120;
  function X(t) { return padL + (t / tmax) * gw; }
  function Y(d) { return padT + gh - (d / dmax) * gh; }

  // grid
  ctx.lineWidth = 1; ctx.strokeStyle = C.line;
  for (var ti = 0; ti <= tmax; ti += 1) {
    ctx.beginPath(); ctx.moveTo(X(ti), padT); ctx.lineTo(X(ti), padT + gh); ctx.stroke();
  }
  for (var di = 0; di <= dmax; di += 10) {
    ctx.beginPath(); ctx.moveTo(padL, Y(di)); ctx.lineTo(padL + gw, Y(di)); ctx.stroke();
  }

  // axes
  ctx.strokeStyle = C.muted; ctx.lineWidth = 1.5;
  ctx.beginPath(); ctx.moveTo(padL, padT); ctx.lineTo(padL, padT + gh); ctx.lineTo(padL + gw, padT + gh); ctx.stroke();

  // axis labels
  ctx.fillStyle = C.body; ctx.font = '12px system-ui, sans-serif';
  ctx.textAlign = 'center';
  ctx.fillText('Time (s)', padL + gw / 2, padT + gh + 20);
  ctx.save();
  ctx.translate(12, padT + gh / 2);
  ctx.rotate(-Math.PI / 2);
  ctx.fillText('Distance (m)', 0, 0);
  ctx.restore();
  ctx.textAlign = 'right';
  ctx.fillText('0', padL - 4, padT + gh + 4);
  ctx.fillText('120', padL - 4, padT + 4);
  ctx.textAlign = 'center';
  ctx.fillText('12', padL + gw, padT + gh + 16);

  // path
  ctx.strokeStyle = C.accentText; ctx.lineWidth = 3; ctx.lineCap = 'round';
  ctx.beginPath();
  var steps = 200;
  for (var i = 0; i <= steps; i++) {
    var t = (i / steps) * tmax;
    var d = distAt(t, steep);
    var x = X(t), y = Y(d);
    if (i === 0) ctx.moveTo(x, y); else ctx.lineTo(x, y);
  }
  ctx.stroke();

  // tangent line
  if (showTangent) {
    ctx.save();
    ctx.beginPath(); ctx.rect(X(0), Y(dmax), X(tmax) - X(0), Y(0) - Y(dmax)); ctx.clip();
    var speed = speedAt(tpos, steep);
    var dAtT = distAt(tpos, steep);
    ctx.setLineDash([6, 5]);
    ctx.strokeStyle = C.info; ctx.lineWidth = 2;
    ctx.beginPath();
    var t1 = 0, t2 = tmax;
    var d1 = dAtT + speed * (t1 - tpos);
    var d2 = dAtT + speed * (t2 - tpos);
    ctx.moveTo(X(t1), Y(d1));
    ctx.lineTo(X(t2), Y(d2));
    ctx.stroke();
    ctx.setLineDash([]);
    ctx.restore();
  }

  // marker dot
  var dm = distAt(tpos, steep);
  ctx.fillStyle = C.accentText;
  ctx.beginPath(); ctx.arc(X(tpos), Y(dm), 6, 0, Math.PI * 2); ctx.fill();
  ctx.strokeStyle = C.surface; ctx.lineWidth = 2; ctx.stroke();
}, 0.7);

function update() {
  var steep = +steepIn.value;
  var tpos = +tposIn.value;
  document.getElementById('steepv').textContent = fmt(steep);
  document.getElementById('tposv').textContent = fmt(tpos);
  var d = distAt(tpos, steep);
  var v = speedAt(tpos, steep);
  document.getElementById('readout').textContent =
    't = ' + fmt(tpos) + ' s, d = ' + fmt(d) + ' m, speed = ' + fmt(v) + ' m/s';
  plot.redraw();
}

steepIn.addEventListener('input', update);
tposIn.addEventListener('input', update);
tangentBtn.addEventListener('click', function () {
  showTangent = !showTangent;
  tangentBtn.setAttribute('aria-pressed', String(showTangent));
  update();
});

update();
